/**
 * Chat conversation summary
 */
export interface ChatConversation {
  id: string;
  title: string | null;
  started: string;
  ended: string | null;
  created: string;
}

/**
 * Chat message with role and content
 */
export interface ChatMessage {
  id: string;
  role: 'user' | 'assistant' | 'tool';
  content: string;
  inputTokens: number | null;
  outputTokens: number | null;
  created: string;
  files?: ChatFileReference[];
}

/**
 * File generated by the LLM and stored server-side
 */
export interface ChatFileReference {
  fileId: string;
  fileName: string;
  contentType: string;
  fileSize: number;
  summary: string | null;
}

/**
 * Streaming chunk received from SignalR
 */
export interface ChatStreamChunk {
  type: 'content' | 'tool_call' | 'tool_result' | 'complete' | 'error' | 'file';
  content: string;
  isComplete: boolean;
  inputTokens: number | null;
  outputTokens: number | null;
  fileId?: string;
  fileName?: string;
  fileSize?: number;
}

/**
 * Request to create a new conversation
 */
export interface CreateConversationRequest {
  title?: string;
}

/**
 * LLM status received from SignalR CheckStatus
 */
export interface ChatLLMStatus {
  llmAvailable: boolean;
  providerName: string | null;
}

/**
 * Prompt history entry stored server-side
 */
export interface ChatPromptHistoryEntry {
  id: string;
  promptText: string;
  created: string;
}

/**
 * Saved favorite prompt for the chat sidebar
 */
export interface ChatFavorite {
  id: string;
  name: string;
  prompt: string;
  pinned?: boolean;
}

/**
 * Chat state for NgRx Signals store
 */
export interface ChatState {
  conversations: ChatConversation[];
  currentConversation: ChatConversation | null;
  messages: ChatMessage[];
  isConnected: boolean;
  llmAvailable: boolean | null;
  llmError: boolean;
  isStreaming: boolean;
  streamingContent: string;
  isLoading: boolean;
  error: string | null;
  pendingFiles: ChatFileReference[];
}
